import 'dart:convert';

/// Structural checks for project files generated by AI or imported from ZIP.
/// These checks are deliberately conservative; they do not replace engine builds.
class NovaProjectValidator {
  static const int maxFiles = 250;
  static const int maxFileBytes = 1024 * 1024;
  static const int maxWorkspaceBytes = 5 * 1024 * 1024;

  static String normalizePath(String path) => path.replaceAll('\\', '/');

  static bool isSafeRelativePath(String path) {
    final normalized = normalizePath(path).trim();
    if (normalized.isEmpty ||
        normalized.startsWith('/') ||
        normalized.contains(':') ||
        normalized.contains('\u0000') ||
        normalized.contains(RegExp(r'[\x00-\x1F\x7F]'))) {
      return false;
    }
    final segments = normalized.split('/');
    if (segments.any((segment) =>
        segment.isEmpty || segment == '.' || segment == '..')) {
      return false;
    }
    return true;
  }

  /// Returns blocking errors for an AI response's files array.
  static List<String> validateGeneratedFiles(List<dynamic> files) {
    final errors = <String>[];
    if (files.length > maxFiles) {
      errors.add('Too many files: maximum is $maxFiles.');
    }
    final seen = <String>{};
    final seenCaseInsensitive = <String>{};
    var totalBytes = 0;
    for (var i = 0; i < files.length; i++) {
      final item = files[i];
      if (item is! Map || item['path'] is! String || item['content'] is! String) {
        errors.add('File entry $i must contain string path and content fields.');
        continue;
      }
      final path = normalizePath(item['path'] as String);
      final content = item['content'] as String;
      if (!isSafeRelativePath(path)) {
        errors.add('Unsafe relative path: \${item['path']}');
        continue;
      }
      if (!seen.add(path)) errors.add('Duplicate file path: $path');
      if (!seenCaseInsensitive.add(path.toLowerCase())) {
        errors.add('File path conflicts on case-insensitive filesystems: $path');
      }
      final bytes = utf8.encode(content).length;
      totalBytes += bytes;
      if (bytes > maxFileBytes) errors.add('File exceeds 1 MiB: $path');
      if (content.isEmpty) errors.add('File is empty: $path');
      if (path.toLowerCase().endsWith('.rbxmx') &&
          !(content.contains('<roblox') &&
            content.contains('<Item class="Model"') &&
            content.contains('</roblox>'))) {
        errors.add('Roblox model XML is missing a roblox root or Model item: $path');
      }
    }
    if (totalBytes > maxWorkspaceBytes) {
      errors.add('Generated files exceed the 5 MiB total limit.');
    }
    return errors;
  }

  /// Checks the existing workspace using the same structural rules.
  static List<String> validateWorkspace(Map<String, String> files) =>
      validateGeneratedFiles(files.entries
          .map((entry) => <String, Object>{
                'path': entry.key,
                'content': entry.value,
              })
          .toList(growable: false));
}
